-- Editorial JSON for local Ausstellung post 21108 (`rohren-fur-die-republik`).
-- Scope: JSON document + enabled flag only. Legacy body, corpus chapter IDs,
-- uploads, source archive posts, and templates remain unchanged.
-- Meta values are hex-encoded so JSON newline escaping survives SQL import.

START TRANSACTION;

DELETE FROM `wp_postmeta`
WHERE `post_id` = 21108
  AND `meta_key` IN ('_iss_editorial_ausstellung', '_iss_editorial_enabled_ausstellung');

INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) VALUES
(21108, '_iss_editorial_ausstellung', CONVERT(UNHEX('') USING utf8mb4)),
(21108, '_iss_editorial_enabled_ausstellung', CONVERT(UNHEX('31') USING utf8mb4));

COMMIT;
